func planOf(pl *port.Cells, pages int32, kind int32) int32 {
	// `pages` rows; every page of `kind`, with a stream at bytes 100 + 50 of the input, a box and a page size.
	var i int32 = 0
	for i < pages {
		port.CellsPush(pl, kind)
		port.CellsPush(pl, 9)
		port.CellsPush(pl, 100)
		port.CellsPush(pl, 50)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 61200)
		port.CellsPush(pl, 79200)
		port.CellsPush(pl, 61200)
		port.CellsPush(pl, 79200)
		// `emon.rasterplan`'s cells: what the page asks (nothing), its witness rows (none), its scripts (none)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 0)
		port.CellsPush(pl, 0)
		// the scan's mode (D564): the host decodes the DCT stream in place
		port.CellsPush(pl, 0)
		i += 1
	}
	return 0
}

func bornPlan(pl *port.Cells, pages int32, ask int32, scripts int32) int32 {
	// `pages` born-digital pages of the plan that ask `ask` (`rp-ask-*`), with the scripts bit set `scripts`.
	var i int32 = 0
	planOf(pl, pages, pageunit.PkBorn())
	for i < pages {
		port.CellsSet(pl, (i*pageunit.PuW())+rasterplan.RpFAsk(), ask)
		port.CellsSet(pl, (i*pageunit.PuW())+rasterplan.RpFScripts(), scripts)
		i += 1
	}
	return 0
}

